import React, { useState } from 'react';

// CSS 파일은 AdminPage.css를 사용한다고 했으니 별도의 import는 필요 없어!
// 하지만 만약 AccountInfoTab만을 위한 CSS 파일이 있다면 import 해주면 돼.
// import './AccountInfoTab.css'; 

const AccountInfoTab = ({ adminInfo }) => {
  const [isEditing, setIsEditing] = useState(false);
  // 초기 formData에 adminInfo 외에 비밀번호 관련 필드를 추가해줬어.
  const [formData, setFormData] = useState({
    ...adminInfo,
    password: '',
    confirmPassword: '',
  });

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleDuplicateCheck = (field) => {
    // 실제 백엔드 중복 확인 API 호출 로직
    alert(`${formData[field]}은(는) 사용 가능합니다! ✅ (API 연동 필요)`);
    console.log(`${field} 중복 확인:`, formData[field]);
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    if (formData.password !== formData.confirmPassword) {
      alert('비밀번호와 비밀번호 확인이 일치하지 않아! 다시 확인해줘! 😵‍💫');
      return;
    }
    // 실제 백엔드 관리자 계정 정보 수정 API 호출 로직
    alert('관리자 계정 정보가 성공적으로 수정되었습니다! 🥳 (API 연동 필요)');
    console.log('수정된 관리자 정보:', formData);
    setIsEditing(false);
  };

  return (
    <div className="tab-content-section account-info-tab"> {/* AdminPage.css의 .tab-content-section 사용 */}
      <h3 className="tab-content-title">계정 정보 {!isEditing ? '보기' : '수정'}</h3> {/* AdminPage.css의 .tab-content-title 사용 */}

      {!isEditing ? (
        <>
          {/* 정보 보기: 내용들 왼쪽 정렬 */}
          <div className="info-item" style={{ justifyContent: 'flex-start' }}>
            <span className="info-label">이름</span>
            <span className="info-value">{adminInfo.name}</span>
          </div>
          <div className="info-item" style={{ justifyContent: 'flex-start' }}>
            <span className="info-label">이메일</span>
            <span className="info-value">{adminInfo.email}</span>
          </div>
          <div className="info-item" style={{ justifyContent: 'flex-start' }}>
            <span className="info-label">닉네임</span>
            <span className="info-value">{adminInfo.role}</span> {/* adminInfo에 닉네임 필드가 따로 없어서 role을 닉네임으로 사용했어. 필요하면 adminInfo 구조를 변경해줘! */}
          </div>
          <div className="button-group" style={{ display: 'flex', justifyContent: 'center', gap: '15px', marginTop: '40px' }}>
            <button className="action-button" onClick={() => setIsEditing(true)}>정보 수정 ✏️</button> {/* AdminPage.css의 .action-button 사용 */}
          </div>
        </>
      ) : (
        <form onSubmit={handleSubmit}>
          {/* 정보 수정 폼 */}
          <div className="info-item">
            <label className="info-label" htmlFor="adminName">이름</label>
            <input
              type="text"
              id="adminName"
              name="name"
              value={formData.name}
              onChange={handleChange}
              className="info-value-input"
              required
            />
          </div>
          <div className="info-item input-with-button"> {/* 중복확인 버튼을 위한 클래스 추가 */}
            <label className="info-label" htmlFor="adminEmail">이메일</label>
            <input
              type="email"
              id="adminEmail"
              name="email"
              value={formData.email}
              onChange={handleChange}
              className="info-value-input"
              required
            />
            <button
              type="button"
              className="small-action-button" // 작은 버튼 스타일을 위한 클래스 추가 (아래 CSS 참고)
              onClick={() => handleDuplicateCheck('email')}
            >
              중복확인
            </button>
          </div>
          <div className="info-item input-with-button"> {/* 중복확인 버튼을 위한 클래스 추가 */}
            <label className="info-label" htmlFor="adminRole">닉네임</label> {/* 닉네임 필드 추가 */}
            <input
              type="text"
              id="adminRole"
              name="role" // adminInfo의 role 필드를 닉네임으로 매핑했어.
              value={formData.role}
              onChange={handleChange}
              className="info-value-input"
              required
            />
            <button
              type="button"
              className="small-action-button" // 작은 버튼 스타일을 위한 클래스 추가 (아래 CSS 참고)
              onClick={() => handleDuplicateCheck('role')} // 닉네임 중복 확인
            >
              중복확인
            </button>
          </div>
          <div className="info-item">
            <label className="info-label" htmlFor="adminPassword">비밀번호</label>
            <input
              type="password"
              id="adminPassword"
              name="password"
              value={formData.password}
              onChange={handleChange}
              className="info-value-input"
              placeholder="새 비밀번호 입력"
            />
          </div>
          <div className="info-item">
            <label className="info-label" htmlFor="adminConfirmPassword">비밀번호 확인</label>
            <input
              type="password"
              id="adminConfirmPassword"
              name="confirmPassword"
              value={formData.confirmPassword}
              onChange={handleChange}
              className="info-value-input"
              placeholder="새 비밀번호 다시 입력"
            />
          </div>
          <div className="button-group" style={{ display: 'flex', justifyContent: 'center', gap: '15px', marginTop: '40px' }}>
            <button type="submit" className="action-button">저장 ✅</button>
            <button type="button" className="action-button secondary" onClick={() => setIsEditing(false)}>취소 ↩️</button>
          </div>
        </form>
      )}
    </div>
  );
};

export default AccountInfoTab;
